import{_ as s,o as a,c as t,a2 as n}from"./chunks/framework.a6FUKr6c.js";const u=JSON.parse('{"title":"WhatsApp","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/whatsapp.md","filePath":"deployment/whatsapp.md","lastUpdated":1794227859000}'),o={name:"deployment/whatsapp.md"};function c(r,e,l,p,d,i){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="whatsapp" tabindex="-1">WhatsApp <a class="header-anchor" href="#whatsapp" aria-label="Permalink to &quot;WhatsApp&quot;">​</a></h1><p><a href="#createwhatsappchat"><code>@chamvi/chat-whatsapp</code></a> connects an agent to a WhatsApp account through WhatsApp Web, using <a href="https://www.npmjs.com/package/baileys" target="_blank" rel="noreferrer">Baileys</a> <code>7.0.0-rc14</code>. The account appears as a linked device; messages from allowed senders start runs, and tools reply in the same chat.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#DCE9F2;">npm </span><span style="color:#E7C58C;">install</span><span style="color:#E7C58C;"> @chamvi/chat-whatsapp</span><span style="color:#E7C58C;"> @chamvi/chat</span><span style="color:#E7C58C;"> @chamvi/core</span><span style="color:#E7C58C;"> @chamvi/http</span><span style="color:#E7C58C;"> chat</span><span style="color:#E7C58C;"> baileys@7.0.0-rc14</span><span style="color:#E7C58C;"> --save</span></span></code></pre></div><p><code>@chamvi/chat</code>, <code>@chamvi/core</code>, <code>chat</code> and <code>baileys</code> are peer dependencies; <code>baileys</code> is pinned to exactly <code>7.0.0-rc14</code>, the version the adapter&#39;s identity rules were verified against. The package uses only <code>@chamvi/chat</code>&#39;s public API: its channel is a <a href="/reference/chat#chatchannel"><code>chatChannel()</code></a> with the WhatsApp hooks passed as <a href="/reference/chat#platform-packages"><code>platform</code></a>, so subscriptions, replies, approvals, memory and trust work as described there.</p><div class="danger custom-block"><p class="custom-block-title">Unofficial protocol</p><p>WhatsApp Web through Baileys is not an official WhatsApp API. WhatsApp can change the protocol, and it can restrict or ban an account that automates it. Use an account you can afford to lose, keep the volume personal, and keep a way back (your previous setup) until the connector has run for a while.</p></div><h2 id="readiness-checklist" tabindex="-1">Readiness checklist <a class="header-anchor" href="#readiness-checklist" aria-label="Permalink to &quot;Readiness checklist&quot;">​</a></h2><p>Before a live cutover:</p><ol><li><strong>A session store.</strong> With <code>@chamvi/app</code>, <a href="#with-chamvi-app"><code>whatsappModule()</code></a> keeps the session sealed in the app store (PostgreSQL through <code>@chamvi/store-db</code> in production) under <code>CHAMVI_ENCRYPTION_KEYS</code>. Without the app, <code>createStoreWhatsAppAuth()</code> does the same over a <a href="#session-store">connection vault</a>, or you write an <code>IWhatsAppAuthProvider</code> that persists the creds and every signal key write atomically, serializes writes, keeps the session secret (it is the account) and takes it exclusively. Baileys&#39; <code>useMultiFileAuthState</code> alone is not that.</li><li><strong>One connector.</strong> One deployment per account, <code>Recreate</code> (stop, then start), one replica. Two processes on one session replace each other (440) and can corrupt the signal state. The <code>agent-app</code> chart&#39;s Recreate strategy fits.</li><li><strong>The sender policy.</strong> List phone number jids and group jids explicitly; <code>{ open: true }</code> lets anyone write, with <code>resolveInvoker</code> as the only gate.</li><li><strong>An approval URL</strong> into the chamvi UI, and an owner principal that can answer there. Approvals are answered in the UI only.</li><li><strong>Memory</strong>, if the agent uses <code>conversation: true</code>: a store with conversations (PostgreSQL through <code>@chamvi/store-db</code> for restart-durable memory) and a <code>conversations.authorize</code> policy. A group is one memory (<code>group:&lt;group jid&gt;</code>), shared by its members.</li><li><strong>Trust.</strong> Runs are tainted by default: tools marked <code>guardWhenTainted</code> need approval. Replies to the source chat are not gated; do not set a <code>defaultAddress</code> unless that chat may receive whatever a tainted run produces.</li></ol><h2 id="pairing" tabindex="-1">Pairing <a class="header-anchor" href="#pairing" aria-label="Permalink to &quot;Pairing&quot;">​</a></h2><p>The first start of an unpaired session emits a QR reference (it rotates periodically until scanned: Baileys shows the first for 60 s, each later one for 20 s). With <code>whatsappModule()</code> it shows on the dashboard&#39;s <a href="/guide/ui#pages">Connections page</a>, live, to a principal holding <code>connection:&lt;name&gt;:write</code>: open <code>/ui/connections/&lt;name&gt;</code> and scan it with the phone (WhatsApp, Linked devices, Link a device). With <code>createWhatsAppChat()</code> it goes to <code>onPairing</code>; render it there. Either way it is never logged. There is no phone-number pairing code yet. Once paired, the session is stored and later starts connect without a QR.</p><h2 id="session-store" tabindex="-1">Session store <a class="header-anchor" href="#session-store" aria-label="Permalink to &quot;Session store&quot;">​</a></h2><p><code>whatsappModule()</code> stores the session as a <strong>connection</strong> of the app: one row per connection (its name, type <code>whatsapp</code> and data key) and one entry per Baileys value (<code>creds</code>, <code>key:&lt;type&gt;:&lt;id&gt;</code>), each sealed with AES-256-GCM under the connection&#39;s data key and bound to its connection and entry name. The data key is wrapped by the first key of <code>CHAMVI_ENCRYPTION_KEYS</code>; the store holds sealed bytes only.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#7F95A6;"># one key: &lt;id&gt;:&lt;base64 of 32 random bytes&gt;</span></span>
<span class="line"><span style="color:#DCE9F2;">CHAMVI_ENCRYPTION_KEYS=</span><span style="color:#E7C58C;">&quot;k1:</span><span style="color:#DCE9F2;">$(</span><span style="color:#E7C58C;">openssl rand -base64 32</span><span style="color:#DCE9F2;">)</span><span style="color:#E7C58C;">&quot;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Topic</th><th>What to know</th></tr></thead><tbody><tr><td>The key</td><td>One <code>CHAMVI_ENCRYPTION_KEYS</code> per app, shared by every replica and pod of it; keep it in a secret (the chart&#39;s <code>secrets</code>). Ids follow the agent-name rule. A malformed value fails the start and <code>chamvi start --check</code>, naming the variable, never echoing the value. <code>chamvi run-job</code> pods do not need it (a job resolves no keyring).</td></tr><tr><td>Rotation</td><td>Put the new key first and keep the old one: <code>k2:&lt;new&gt;,k1:&lt;old&gt;</code>. New connections use <code>k2</code>; rows wrapped under <code>k1</code> stay readable. There is no re-encrypt command, so keep <code>k1</code> while any row uses it.</td></tr><tr><td>Losing the key</td><td>The session cannot be opened (<code>decryption_failed</code>, naming the missing key id, never key material), and the connection shows <code>failed</code>: <strong>Reset session</strong> recreates the connection under the lease with a fresh data key under the first key of <code>CHAMVI_ENCRYPTION_KEYS</code> (the old session is deleted), then pair again. No database access is needed.</td></tr><tr><td>Exclusive</td><td>A process holds the session through the store lock <code>connection:&lt;name&gt;</code> (TTL <code>leaseTtlMs</code>, default 60 s, renewed every third of it), each session under its own owner token; every write is fenced by that lease in the same transaction, so a session that lost it writes nothing.</td></tr><tr><td>kill -9</td><td>The next start comes up, shows the connection <code>held_elsewhere</code> and retries on its own; once the old lease expires (at most <code>leaseTtlMs</code>, plus one backoff step of at most 30 s) it connects with the stored session. Every stored batch of signal keys is all or nothing.</td></tr><tr><td>Reset</td><td>A logged-out session, one that cannot be opened (a lost key), or one you want to drop: <strong>Reset session</strong> on the Connections page (<code>POST /connections/&lt;name&gt;/reset</code>, <code>connection:&lt;name&gt;:write</code>, <code>202</code> once started) deletes the stored session under the lease, recreates it with a fresh data key and reconnects, so a new QR appears; no restart. While the connection is <code>held_elsewhere</code> the reset is refused (<code>409</code>) and nothing is cleared or queued: reset it on the replica that holds it, or once the stale lease expired.</td></tr></tbody></table><h2 id="connection-and-recovery" tabindex="-1">Connection and recovery <a class="header-anchor" href="#connection-and-recovery" aria-label="Permalink to &quot;Connection and recovery&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Event</th><th>What happens</th></tr></thead><tbody><tr><td>Unexpected close (network, server restart)</td><td>Reconnects with backoff on the clock: 2 s growing by 1.8 to 30 s, ±25 %, 12 attempts in a row, then <code>whatsapp_connection</code> and it stays disconnected until the channel restarts</td></tr><tr><td>Logout (401: the device was removed on the phone)</td><td>Status <code>logged-out</code>, <code>whatsapp_logged_out</code>, no reconnect. Reset the session (dashboard or <code>reset()</code>) and pair again; the lease stays held meanwhile</td></tr><tr><td>Session held at start (another process, or a crashed one within its lease TTL)</td><td>Status <code>held-elsewhere</code>; the start does not fail: it retries with the reconnect backoff, without a cap, until the lease is free or the channel stops (reported once per hold, <code>whatsapp_auth</code>)</td></tr><tr><td>Session store failing (the database, a wrong key)</td><td>Status <code>failed</code>, <code>whatsapp_auth</code> with the cause; retried with the backoff up to 12 times, then <code>whatsapp_connection</code> and it stays failed until a reset or restart</td></tr><tr><td>Replaced (440: another client took the session)</td><td><code>whatsapp_connection</code>, no reconnect: stop the other connector first</td></tr><tr><td>Stop</td><td>Ends the socket (at most 30 s), refuses later auth writes, then waits for pending ones and flushes the lease, then releases it, within another 30 s. A failed flush is reported (<code>whatsapp_auth</code>) and the lease released all the same (the failed writes are lost); writes past the 30 s are reported and the lease is released once they settle. A dead link that holds the socket&#39;s end for its 30 s does not keep the lease</td></tr></tbody></table><p>A stop takes at most the socket&#39;s end (30 s) and the auth settling (30 s), plus the channel&#39;s wait for messages still being accepted (<code>CHAT_STOP_TIMEOUT_MS</code>, 30 s) and the Chat&#39;s shutdown. Only when every phase runs to its bound does that reach the CLI&#39;s 90 s force exit (<code>CHAMVI_FORCE_EXIT_MS</code>), which the chart&#39;s 120 s termination grace covers; raise <code>CHAMVI_FORCE_EXIT_MS</code> (below the grace) if a stop must never be cut short.</p><p><code>setup.status()</code> reports the connection (<code>connected</code> only after Baileys&#39; <code>open</code>), <code>onStatus(status)</code> gets every change; poll or listen for a readiness signal. Sends fail while it is not <code>connected</code>.</p><p>Baileys&#39; own logger is silent, because its lines carry pairing material and session details; this also hides its decrypt and LID warnings. Errors reach <code>onError</code> without message text.</p><h2 id="createwhatsappchat" tabindex="-1">createWhatsAppChat <a class="header-anchor" href="#createwhatsappchat" aria-label="Permalink to &quot;createWhatsAppChat&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">function</span><span style="color:#DCE9F2;"> createWhatsAppChat(options: WhatsAppChatOptions): WhatsAppChatSetup; </span><span style="color:#7F95A6;">// @chamvi/chat-whatsapp</span></span>
<span class="line"><span style="color:#7F95A6;">// WhatsAppChatSetup = { chat, ingress, channel, status(): WhatsAppConnectionStatus, reset(): Promise&lt;void&gt;, conversation(input): ConversationRef }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> WHATSAPP_ADAPTER_NAME: </span><span style="color:#E7C58C;">&#39;whatsapp&#39;</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> WHATSAPP_RECONNECT: { initialMs: </span><span style="color:#E7C58C;">2000</span><span style="color:#DCE9F2;">; factor: </span><span style="color:#E7C58C;">1.8</span><span style="color:#DCE9F2;">; maxMs: </span><span style="color:#E7C58C;">30_000</span><span style="color:#DCE9F2;">; jitter: </span><span style="color:#E7C58C;">0.25</span><span style="color:#DCE9F2;">; maxAttempts: </span><span style="color:#E7C58C;">12</span><span style="color:#DCE9F2;"> };</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> WHATSAPP_SHUTDOWN_TIMEOUT_MS: </span><span style="color:#E7C58C;">30_000</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#7F95A6;">// error codes: &#39;whatsapp_auth&#39;, &#39;whatsapp_connection&#39;, &#39;whatsapp_logged_out&#39; (WHATSAPP_*_ERROR_CODE)</span></span></code></pre></div><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> whatsapp = createWhatsAppChat({</span></span>
<span class="line"><span style="color:#7F95A6;">    // a non-secret alias of the account (the conversation account)</span></span>
<span class="line"><span style="color:#DCE9F2;">    account: </span><span style="color:#E7C58C;">&#39;assistant&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    auth,</span></span>
<span class="line"><span style="color:#DCE9F2;">    state,</span></span>
<span class="line"><span style="color:#7F95A6;">    // placeholder jids: phone number jids, no device suffix; groups need a mention by default</span></span>
<span class="line"><span style="color:#DCE9F2;">    policy: { senders: [</span><span style="color:#E7C58C;">&#39;491701111111@s.whatsapp.net&#39;</span><span style="color:#DCE9F2;">], groups: [</span><span style="color:#E7C58C;">&#39;120363000000000001@g.us&#39;</span><span style="color:#DCE9F2;">] },</span></span>
<span class="line"><span style="color:#7F95A6;">    // undefined denies the message</span></span>
<span class="line"><span style="color:#DCE9F2;">    resolveInvoker: (identity) </span><span style="color:#8FD0F2;">=&gt;</span><span style="color:#DCE9F2;"> ({</span></span>
<span class="line"><span style="color:#DCE9F2;">        id: identity.sender,</span></span>
<span class="line"><span style="color:#DCE9F2;">        kind: </span><span style="color:#E7C58C;">&#39;whatsapp&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">        permissions: [],</span></span>
<span class="line"><span style="color:#DCE9F2;">    }),</span></span>
<span class="line"><span style="color:#DCE9F2;">    approvalUrl,</span></span>
<span class="line"><span style="color:#7F95A6;">    // render the QR for the phone; never log it</span></span>
<span class="line"><span style="color:#DCE9F2;">    onPairing: ({ qr }) </span><span style="color:#8FD0F2;">=&gt;</span><span style="color:#DCE9F2;"> showQr(qr),</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Option</th><th></th></tr></thead><tbody><tr><td><code>account</code></td><td>Required. A non-secret alias of the account (the conversation account), not its phone number</td></tr><tr><td><code>auth</code></td><td>Required. An <code>IWhatsAppAuthProvider</code> (below), e.g. <code>createStoreWhatsAppAuth()</code></td></tr><tr><td><code>policy</code></td><td>Required. <code>{ senders, groups?, requireGroupMention? }</code> or <code>{ open: true, groups?, requireGroupMention? }</code> (below)</td></tr><tr><td><code>resolveInvoker(identity)</code></td><td>Required. The invoker of an allowed message&#39;s runs; <code>undefined</code> denies the message</td></tr><tr><td><code>state</code></td><td>Required. The Chat SDK <code>StateAdapter</code> of the <code>Chat</code></td></tr><tr><td><code>approvalUrl(ref)</code></td><td>Required. The approval link, <code>ref = { runId, approvalId, agent }</code> (ids only)</td></tr><tr><td><code>onPairing({ qr })</code></td><td>Required. Gets the QR reference to render while the account is not paired; never a log or <code>onError</code></td></tr><tr><td><code>onStatus(status)</code></td><td>Called on every status change; a throw is reported, the change stands</td></tr><tr><td><code>name</code>, <code>untrusted</code>, <code>timeoutMs</code></td><td>As for <a href="/reference/chat#chatchannel"><code>chatChannel()</code></a></td></tr><tr><td><code>clock</code></td><td>The connector&#39;s clock (backoff, shutdown bound); default the engine&#39;s</td></tr><tr><td><code>onError</code></td><td>Failures nobody awaits; default <code>console.error</code></td></tr><tr><td><code>logger</code>, <code>userName</code></td><td>The Chat SDK logger (default level <code>warn</code>) and bot user name (default <code>chamvi</code>)</td></tr><tr><td><code>socketOptions</code></td><td>Further Baileys <code>SocketConfig</code> fields (<code>version</code>, <code>browser</code>, ...); <code>auth</code> and <code>logger</code> are chamvi&#39;s</td></tr><tr><td><code>socketFactory</code></td><td>Default Baileys&#39; <code>makeWASocket</code>; tests pass a fake</td></tr></tbody></table><p>Throws <code>InvalidAgentDefinitionError</code> for a missing or malformed option. The factory acquires nothing and builds no socket; neither does <code>chamvi start --check</code>.</p><h3 id="sender-policy" tabindex="-1">Sender policy <a class="header-anchor" href="#sender-policy" aria-label="Permalink to &quot;Sender policy&quot;">​</a></h3><p>Policy entries are normalized jids, never names: senders are phone number jids (<code>&lt;digits&gt;@s.whatsapp.net</code>, no device suffix), groups group jids (<code>&lt;id&gt;@g.us</code>). Errors name the option and index, never the value.</p><table tabindex="0"><thead><tr><th>Message</th><th>Starts runs when</th></tr></thead><tbody><tr><td>Direct</td><td>The sender is listed (or <code>open</code>), and <code>resolveInvoker</code> names an invoker</td></tr><tr><td>Group</td><td>The group is listed, the participant is listed (or <code>open</code>), the bot is mentioned (unless <code>requireGroupMention: false</code>), and <code>resolveInvoker</code> names an invoker</td></tr></tbody></table><p>The identity (<code>WhatsAppIdentity { account, chat, sender, group, mentioned }</code>) is authenticated: the sender of a group message is its participant, never the group jid; a device suffix is removed; a LID sender resolves to a phone number only through the stanza&#39;s server-provided alternative (<code>participantAlt</code>/<code>remoteJidAlt</code>) or Baileys&#39; LID mapping store, else the message is denied (an unresolved identity never inherits another&#39;s permissions). The bot&#39;s own messages are ignored. Denied messages are dropped silently: no run, no reply, no download.</p><h3 id="auth-provider" tabindex="-1">Auth provider <a class="header-anchor" href="#auth-provider" aria-label="Permalink to &quot;Auth provider&quot;">​</a></h3><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">interface</span><span style="color:#DCE9F2;"> IWhatsAppAuthProvider {</span></span>
<span class="line"><span style="color:#8FD0F2;">    readonly</span><span style="color:#DCE9F2;"> supportsReset?: boolean; </span><span style="color:#7F95A6;">// true when acquire honours reset; without it reset() is refused</span></span>
<span class="line"><span style="color:#DCE9F2;">    acquire(signal: AbortSignal, options?: { reset?: boolean }): Promise&lt;WhatsAppAuthLease&gt;;</span></span>
<span class="line"><span style="color:#DCE9F2;">}</span></span>
<span class="line"><span style="color:#8FD0F2;">type</span><span style="color:#DCE9F2;"> WhatsAppAuthLease = {</span></span>
<span class="line"><span style="color:#DCE9F2;">    auth: AuthenticationState;     </span><span style="color:#7F95A6;">// Baileys creds and signal key store (get, set, clear?)</span></span>
<span class="line"><span style="color:#DCE9F2;">    saveCreds(): Promise&lt;void&gt;;    </span><span style="color:#7F95A6;">// persists auth.creds, serialized with key writes</span></span>
<span class="line"><span style="color:#DCE9F2;">    flush(): Promise&lt;void&gt;;        </span><span style="color:#7F95A6;">// resolves once every accepted write is durable</span></span>
<span class="line"><span style="color:#DCE9F2;">    release(): Promise&lt;void&gt;;      </span><span style="color:#7F95A6;">// gives the location up</span></span>
<span class="line"><span style="color:#DCE9F2;">    lost?: Promise&lt;unknown&gt;;       </span><span style="color:#7F95A6;">// resolves when the provider lost the session (e.g. its lease)</span></span>
<span class="line"><span style="color:#DCE9F2;">};</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">function</span><span style="color:#DCE9F2;"> createStoreWhatsAppAuth(options: StoreWhatsAppAuthOptions): IWhatsAppAuthProvider; </span><span style="color:#7F95A6;">// @chamvi/chat-whatsapp</span></span>
<span class="line"><span style="color:#7F95A6;">// StoreWhatsAppAuthOptions = { vault: IConnectionVault, connection: string, owner?: string, leaseTtlMs?: number }</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> WHATSAPP_CONNECTION_TYPE: </span><span style="color:#E7C58C;">&#39;whatsapp&#39;</span><span style="color:#DCE9F2;">;</span></span></code></pre></div><p><code>createStoreWhatsAppAuth()</code> is the provider <code>whatsappModule()</code> uses: over a vault (<code>createConnectionVault({ store, keyring, clock })</code> from <code>@chamvi/core</code>, <code>store.connections</code> required, <code>createKeyring()</code>/<code>parseKeyring()</code> for the keys) it opens the connection <code>connection</code> of type <code>whatsapp</code>, refused with <code>ConnectionHeldError</code> (<code>connection_held</code>) while another owner holds it, and maps every key-store write to one sealed, fenced batch.</p><p><code>acquire</code> loads the session and takes its location exclusively (a second holder is refused with <code>ConnectionHeldError</code>: the connection shows <code>held-elsewhere</code> and retries). chamvi calls <code>saveCreds</code> and the key store only while the lease is in use: once the connection closes, every later call is refused (<code>InvalidRunStateError</code>). On stop it ends the socket (bounded by <code>WHATSAPP_SHUTDOWN_TIMEOUT_MS</code>), then waits for pending writes, <code>flush</code>es and <code>release</code>s, within a second <code>WHATSAPP_SHUTDOWN_TIMEOUT_MS</code> (no write is admitted after the close, so a dead link&#39;s end never eats into it); a failed <code>flush</code> is reported (<code>whatsapp_auth</code>) and the lease released all the same, and past the bound the lease is released once the pending writes settle. A lease that arrives after the stop is released at once. A reset acquires with <code>{ reset: true }</code>: once it holds the location the provider discards the stored session (creds and keys, also one it cannot load) and hands out an empty one; <code>createStoreWhatsAppAuth()</code> recreates the connection (<code>vault.open(..., { recreate: true })</code>).</p><h3 id="connection" tabindex="-1">Connection <a class="header-anchor" href="#connection" aria-label="Permalink to &quot;Connection&quot;">​</a></h3><p><code>status()</code>: <code>stopped</code>, <code>connecting</code>, <code>pairing</code> (a QR is out), <code>connected</code> (an <code>open</code> event), <code>disconnected</code>, <code>logged-out</code>, <code>held-elsewhere</code> (the session is held by another process), <code>failed</code> (the session store failed). <code>reset()</code> clears the session and pairs again without restarting the channel (<code>InvalidRunStateError</code> while it is not started, while it is <code>held-elsewhere</code>, or when its acquire finds the session held: nothing is cleared then, and nothing later). Sends go out only while <code>connected</code>. An unexpected close reconnects after <code>min(30 s, 2 s * 1.8^n)</code> ±25 % on the clock, at most 12 times in a row (reset by an open), then reports <code>whatsapp_connection</code> and stays disconnected. A logout (401) reports <code>whatsapp_logged_out</code> and a replacing session (440) <code>whatsapp_connection</code>; neither reconnects.</p><h3 id="cron-runs-in-a-conversation" tabindex="-1">Cron runs in a conversation <a class="header-anchor" href="#cron-runs-in-a-conversation" aria-label="Permalink to &quot;Cron runs in a conversation&quot;">​</a></h3><p><code>setup.conversation({ chat })</code> returns the <code>ConversationRef</code> of a chat for <a href="/guide/scheduler#inside-a-conversation"><code>cron.on(expression, { conversation, text })</code></a>: the identity intake computes for a message there (audience <code>direct:&lt;jid&gt;</code> or <code>group:&lt;jid&gt;</code>), and the chat&#39;s address. <code>chat</code> is a normalized phone number jid (<code>&lt;digits&gt;@s.whatsapp.net</code>, a direct chat) or group jid (<code>&lt;id&gt;@g.us</code>); anything else throws <code>InvalidAgentDefinitionError</code>.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#DCE9F2;">cron.on(</span><span style="color:#E7C58C;">&#39;0 7 * * *&#39;</span><span style="color:#DCE9F2;">, {</span></span>
<span class="line"><span style="color:#DCE9F2;">    conversation: whatsapp.conversation({ chat: </span><span style="color:#E7C58C;">&#39;491701111111@s.whatsapp.net&#39;</span><span style="color:#DCE9F2;"> }),</span></span>
<span class="line"><span style="color:#DCE9F2;">    text: </span><span style="color:#E7C58C;">&#39;Send me my morning briefing.&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span></code></pre></div><p>A send goes out only while the connection is <code>connected</code>, as any reply.</p><h3 id="delivery" tabindex="-1">Delivery <a class="header-anchor" href="#delivery" aria-label="Permalink to &quot;Delivery&quot;">​</a></h3><p>A send posts the raw text to the chat&#39;s jid with a message id derived from the send&#39;s key (<code>3EB0</code> + 36 hex of its SHA-256), so a retry reuses the id. Whether WhatsApp drops such a duplicate is not verified: delivery is at least once.</p><h3 id="with-chamvi-app" tabindex="-1">With @chamvi/app <a class="header-anchor" href="#with-chamvi-app" aria-label="Permalink to &quot;With @chamvi/app&quot;">​</a></h3><p><code>whatsappModule()</code> (<code>@chamvi/chat-whatsapp/module</code>) is the production path: the session in the app store, pairing and reset on the dashboard.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#7F95A6;">// the session lives sealed in the app store, under CHAMVI_ENCRYPTION_KEYS</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> phone = whatsappModule({</span></span>
<span class="line"><span style="color:#7F95A6;">    // the connection: its lease, its sealed entries, /connections/whatsapp in the dashboard</span></span>
<span class="line"><span style="color:#DCE9F2;">    connection: </span><span style="color:#E7C58C;">&#39;whatsapp&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    account: </span><span style="color:#E7C58C;">&#39;assistant&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    state,</span></span>
<span class="line"><span style="color:#DCE9F2;">    policy: { senders: [</span><span style="color:#E7C58C;">&#39;491701111111@s.whatsapp.net&#39;</span><span style="color:#DCE9F2;">] },</span></span>
<span class="line"><span style="color:#DCE9F2;">    resolveInvoker: (identity) </span><span style="color:#8FD0F2;">=&gt;</span><span style="color:#DCE9F2;"> ({</span></span>
<span class="line"><span style="color:#DCE9F2;">        id: identity.sender,</span></span>
<span class="line"><span style="color:#DCE9F2;">        kind: </span><span style="color:#E7C58C;">&#39;whatsapp&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">        permissions: [],</span></span>
<span class="line"><span style="color:#DCE9F2;">    }),</span></span>
<span class="line"><span style="color:#7F95A6;">    // approvalUrl defaults to the dashboard under CHAMVI_PUBLIC_URL</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">export</span><span style="color:#8FD0F2;"> const</span><span style="color:#DCE9F2;"> phoneAssistant = defineModelAgent({</span></span>
<span class="line"><span style="color:#DCE9F2;">    name: </span><span style="color:#E7C58C;">&#39;assistant&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    model,</span></span>
<span class="line"><span style="color:#DCE9F2;">    instructions: </span><span style="color:#E7C58C;">&#39;Answer with the reply tool.&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    conversation: </span><span style="color:#8FD0F2;">true</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    channels: [phone.on()],</span></span>
<span class="line"><span style="color:#DCE9F2;">    tools: { reply },</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">export</span><span style="color:#8FD0F2;"> const</span><span style="color:#DCE9F2;"> phoneApp = createApp({</span></span>
<span class="line"><span style="color:#DCE9F2;">    agents: [phoneAssistant],</span></span>
<span class="line"><span style="color:#7F95A6;">    // no chatModule: whatsappModule contributes the channel and the connection itself</span></span>
<span class="line"><span style="color:#DCE9F2;">    modules: [phone],</span></span>
<span class="line"><span style="color:#DCE9F2;">    conversations: { authorize: ({ agent }) </span><span style="color:#8FD0F2;">=&gt;</span><span style="color:#DCE9F2;"> agent === </span><span style="color:#E7C58C;">&#39;assistant&#39;</span><span style="color:#DCE9F2;"> },</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span></code></pre></div><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">function</span><span style="color:#DCE9F2;"> whatsappModule(options: WhatsAppModuleOptions): WhatsAppModule; </span><span style="color:#7F95A6;">// @chamvi/chat-whatsapp/module</span></span>
<span class="line"><span style="color:#7F95A6;">// WhatsAppModuleOptions = WhatsAppChatOptions without auth, onPairing, onStatus</span></span>
<span class="line"><span style="color:#7F95A6;">//   &amp; { connection: string; leaseTtlMs?: number; approvalUrl?: WhatsAppChatOptions[&#39;approvalUrl&#39;] }</span></span>
<span class="line"><span style="color:#7F95A6;">// WhatsAppModule: { channel, handle, on(), to(), conversation(), status(), reset() }</span></span></code></pre></div><p>The factory builds the channel at once (nothing read, acquired or connected), so agents subscribe with <code>module.on()</code>. In <code>setup</code> (start mode, <code>chamvi start --check</code> included) it resolves the keyring from <code>CHAMVI_ENCRYPTION_KEYS</code> (unset or malformed: setup fails naming the variable) and builds the vault over the app store, contributes the channel to <code>AppToken.CHANNELS</code> and the connection to <code>AppToken.CONNECTIONS</code> (the dashboard&#39;s Connections page and <code>/connections</code>); <code>approvalUrl</code> defaults to the dashboard under <code>CHAMVI_PUBLIC_URL</code> (one of them is required). A <code>run-job</code> contributes the channel only, a migration nothing. The lease is taken only when the engine starts the channel, so a check acquires and writes nothing. Use it instead of <code>chatModule()</code>, not with it.</p><p>With your own provider, <code>chatModule()</code> contributes a <code>createWhatsAppChat()</code> channel; it adds no env variable and constructs nothing, so <code>chamvi start --check</code> neither acquires the auth lease nor connects:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">export</span><span style="color:#8FD0F2;"> const</span><span style="color:#DCE9F2;"> whatsappAssistant = defineModelAgent({</span></span>
<span class="line"><span style="color:#DCE9F2;">    name: </span><span style="color:#E7C58C;">&#39;assistant&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    model,</span></span>
<span class="line"><span style="color:#DCE9F2;">    instructions: </span><span style="color:#E7C58C;">&#39;Answer with the reply tool.&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    conversation: </span><span style="color:#8FD0F2;">true</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    channels: [whatsapp.channel.on()],</span></span>
<span class="line"><span style="color:#DCE9F2;">    tools: { reply },</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">export</span><span style="color:#8FD0F2;"> const</span><span style="color:#DCE9F2;"> whatsappApp = createApp({</span></span>
<span class="line"><span style="color:#DCE9F2;">    agents: [whatsappAssistant],</span></span>
<span class="line"><span style="color:#DCE9F2;">    modules: [chatModule({ channel: whatsapp.channel })],</span></span>
<span class="line"><span style="color:#DCE9F2;">    conversations: { authorize: ({ agent }) </span><span style="color:#8FD0F2;">=&gt;</span><span style="color:#DCE9F2;"> agent === </span><span style="color:#E7C58C;">&#39;assistant&#39;</span><span style="color:#DCE9F2;"> },</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span></code></pre></div><h2 id="what-is-not-guaranteed" tabindex="-1">What is not guaranteed <a class="header-anchor" href="#what-is-not-guaranteed" aria-label="Permalink to &quot;What is not guaranteed&quot;">​</a></h2><ul><li><strong>No lossless or offline ingestion.</strong> A message that arrives while the connector is down, or that the process loses before it is stored as runs, is not fetched later. Platform history is not read.</li><li><strong>Stop during a decrypt.</strong> A message whose signal key commit arrives after the stop refused auth writes is not processed; Baileys may retry the commit for about 30 s, refused each time.</li><li><strong>At least once delivery.</strong> A send that times out (30 s) may still be delivered; the retry reuses the message id, but whether WhatsApp drops the duplicate is unverified.</li><li><strong>Text only.</strong> Messages with media are refused (reported, no run); replies are text up to 4096 characters, never split.</li></ul>`,49)])])}const y=s(o,[["render",c]]);export{u as __pageData,y as default};
